   244→}
   245→```
   246→
   247→---
   248→
   249→## 7. Card Endpoints
   250→
   251→### 7.1 Update Card
   252→
   253→#### PATCH /sessions/:sessionId/cards/:cardId
   254→
   255→```typescript
   256→// Request
   257→interface UpdateCardRequest {
   258→  title?: string;
