   266→}
   267→```
   268→
   269→### 7.2 Delete Card
   270→
   271→#### DELETE /sessions/:sessionId/cards/:cardId
   272→
   273→```typescript
   274→// Response
   275→interface DeleteCardResponse {
   276→  success: boolean;
   277→  affectedCards: string[];  // IDs of cards renumbered
   278→}
   279→```
   280→
   281→### 7.3 Convert Card
   282→
   283→#### POST /sessions/:sessionId/cards/:cardId/convert
   284→
   285→```typescript
   286→// Request
   287→interface ConvertCardRequest {
   288→  to: "task" | "document" | "github-issue" | "whitepaper-seed" | "summary";
   289→  options?: ConvertOptions;
   290→}
   291→
   292→interface ConvertOptions {
   293→  includeUserMessage?: boolean;
   294→  includeCode?: boolean;
   295→  format?: "markdown" | "plain";
   296→}
   297→
   298→// Response
   299→interface ConvertCardResponse {
   300→  artifact: Artifact;
   301→}
   302→
   303→interface Artifact {
   304→  type: string;
   305→  content: string;
   306→  metadata: Record<string, unknown>;
   307→}
   308→```
   309→
   310→---
   311→
   312→## 8. Branch Endpoints
   313→
   314→### 8.1 Create Branch
   315→
   316→#### POST /sessions/:sessionId/branches
   317→
   318→```typescript
   319→// Request
   320→interface CreateBranchRequest {
   321→  name: string;
   322→  fromCardId: string;    // Branch point
   323→}
   324→
   325→// Response
   326→interface CreateBranchResponse {
   327→  branch: Branch;
   328→}
   329→```
   330→
   331→### 8.2 Switch Branch
   332→
   333→#### POST /sessions/:sessionId/branches/:branchId/activate
   334→
   335→```typescript
   336→// Response
   337→interface SwitchBranchResponse {
   338→  state: ApplicationState;  // Full state with new branch
   339→}
   340→```
   341→
   342→### 8.3 List Branches
   343→
   344→#### GET /sessions/:sessionId/branches
   345→
   346→```typescript
   347→// Response
   348→interface ListBranchesResponse {
   349→  branches: Branch[];
   350→  activeBranchId: string;
   351→}
   352→```
   353→
   354→---
   355→
   356→## 9. Thread Endpoints
   357→
   358→### 9.1 Create Thread
   359→
   360→#### POST /sessions/:sessionId/threads
   361→
   362→```typescript
   363→// Request
   364→interface CreateThreadRequest {
   365→  title?: string;
   366→  fromCardId?: string;   // Optional: create from existing card
   367→}
   368→
   369→// Response
   370→interface CreateThreadResponse {
   371→  thread: ThreadState;
   372→}
   373→```
   374→
   375→### 9.2 Send Thread Message
   376→
   377→#### POST /sessions/:sessionId/threads/:threadId/messages
   378→
   379→```typescript
   380→// Request
   381→interface SendThreadMessageRequest {
   382→  content: string;
   383→}
   384→
   385→// Response
   386→interface SendThreadMessageResponse {
   387→  cardId: string;
   388→  status: "streaming" | "complete";
   389→}
   390→```
   391→
   392→### 9.3 Update Thread
   393→
   394→#### PATCH /sessions/:sessionId/threads/:threadId
   395→
   396→```typescript
   397→// Request
   398→interface UpdateThreadRequest {
   399→  title?: string;
   400→  state?: "active" | "minimized" | "closed";
   401→  isPinned?: boolean;
