   405→// Response
   406→interface UpdateThreadResponse {
   407→  thread: ThreadState;
   408→}
   409→```
   410→
   411→### 9.4 Promote Thread Content
   412→
   413→#### POST /sessions/:sessionId/threads/:threadId/promote
   414→
   415→```typescript
   416→// Request
   417→interface PromoteThreadRequest {
   418→  cardIds?: string[];     // Specific cards, or omit for entire thread
   419→  insertPosition: "end" | "after-selected" | number;
   420→  generateSummary?: boolean;
   421→}
   422→
   423→// Response
   424→interface PromoteThreadResponse {
   425→  promotedCards: TurnCard[];
   426→  newCarouselState: CarouselState;
   427→}
   428→```
   429→
   430→---
   431→
   432→## 10. Context Endpoints
   433→
   434→### 10.1 List Personas
   435→
   436→#### GET /personas
   437→
   438→```typescript
   439→// Response
   440→interface ListPersonasResponse {
   441→  personas: Persona[];
   442→}
   443→
   444→interface Persona {
   445→  id: string;
   446→  name: string;
   447→  description: string;
   448→  domains: string[];
   449→  isDefault: boolean;
   450→}
   451→```
   452→
   453→### 10.2 List Documents
   454→
   455→#### GET /sessions/:sessionId/documents
   456→
   457→```typescript
   458→// Response
   459→interface ListDocumentsResponse {
   460→  documents: Document[];
   461→}
   462→
   463→interface Document {
   464→  id: string;
   465→  name: string;
   466→  type: "file" | "url" | "knowledge-base";
   467→  status: "pinned" | "active" | "available" | "muted";
   468→  size?: number;
   469→  excerpt?: string;
   470→}
   471→```
   472→
   473→### 10.3 Add Document
   474→
   475→#### POST /sessions/:sessionId/documents
   476→
   477→```typescript
   478→// Request
   479→interface AddDocumentRequest {
   480→  type: "file" | "url";
   481→  content: string;       // Base64 for file, URL for URL
   482→  name?: string;
   483→}
   484→
   485→// Response
   486→interface AddDocumentResponse {
   487→  document: Document;
   488→}
   489→```
   490→
   491→### 10.4 Update Document Status
   492→
   493→#### PATCH /sessions/:sessionId/documents/:documentId
   494→
   495→```typescript
   496→// Request
   497→interface UpdateDocumentRequest {
   498→  status: "pinned" | "active" | "available" | "muted";
   499→}
   500→
   501→// Response
   502→interface UpdateDocumentResponse {
