   506→
   507→---
   508→
   509→## 11. Search Endpoints
   510→
   511→### 11.1 Search Conversation
   512→
   513→#### GET /sessions/:sessionId/search
   514→
   515→```typescript
   516→// Query parameters
   517→interface SearchQuery {
   518→  q: string;
   519→  scope?: "current" | "all-sessions" | "knowledge";
   520→  limit?: number;
   521→}
   522→
   523→// Response
   524→interface SearchResponse {
   525→  results: SearchResult[];
   526→  total: number;
   527→}
   528→
   529→interface SearchResult {
   530→  type: "card" | "memory" | "knowledge";
   531→  id: string;
   532→  sessionId?: string;
   533→  title: string;
   534→  excerpt: string;
   535→  relevance: number;
   536→  timestamp: string;
   537→}
   538→```
   539→
   540→---
   541→
   542→## 12. Export Endpoints
   543→
   544→### 12.1 Export Session
   545→
   546→#### POST /sessions/:sessionId/export
   547→
   548→```typescript
   549→// Request
   550→interface ExportRequest {
   551→  format: "json" | "markdown" | "pdf";
   552→  includeThreads?: boolean;
   553→  includeBranches?: boolean;
   554→  branchId?: string;     // Specific branch, or omit for all
   555→}
   556→
   557→// Response
   558→interface ExportResponse {
   559→  downloadUrl: string;
   560→  expiresAt: string;
   561→}
   562→```
   563→
   564→---
   565→
   566→## 13. WebSocket API
   567→
   568→### 13.1 Connection
   569→
   570→```
   571→wss://api.carousel.example.com/v1/ws?token=<jwt_token>
   572→```
   573→
   574→### 13.2 Message Format
   575→
   576→```typescript
   577→interface WSMessage {
   578→  type: WSMessageType;
   579→  payload: unknown;
   580→  timestamp: string;
   581→  correlationId?: string;  // Links response to request
   582→}
   583→
   584→type WSMessageType =
   585→  // Client → Server
   586→  | "PING"
   587→  | "SUBSCRIBE"
   588→  | "UNSUBSCRIBE"
   589→  | "ACTION"
   590→
   591→  // Server → Client
   592→  | "PONG"
   593→  | "STATE_UPDATE"
   594→  | "STREAM_START"
   595→  | "STREAM_CHUNK"
   596→  | "STREAM_END"
   597→  | "ERROR";
   598→```
   599→
   600→### 13.3 Subscription
   601→
   602→```typescript
   603→// Subscribe to session updates
   604→{
   605→  "type": "SUBSCRIBE",
   606→  "payload": {
   607→    "sessionId": "sess_abc123"
   608→  }
   609→}
   610→
   611→// Response
   612→{
   613→  "type": "STATE_UPDATE",
   614→  "payload": {
   615→    "state": { /* ApplicationState */ }
   616→  }
   617→}
   618→```
   619→
   620→### 13.4 Streaming Response
   621→
   622→When a message is sent, the AI response streams via WebSocket:
   623→
   624→```typescript
   625→// Stream start
   626→{
   627→  "type": "STREAM_START",
   628→  "payload": {
   629→    "cardId": "card_007",
   630→    "sessionId": "sess_abc123"
   631→  }
   632→}
   633→
   634→// Stream chunks (multiple)
   635→{
   636→  "type": "STREAM_CHUNK",
   637→  "payload": {
   638→    "cardId": "card_007",
   639→    "content": "The carousel architecture ",
   640→    "index": 0
   641→  }
   642→}
   643→
   644→{
   645→  "type": "STREAM_CHUNK",
   646→  "payload": {
   647→    "cardId": "card_007",
   648→    "content": "treats each turn as a card...",
   649→    "index": 1
   650→  }
   651→}
   652→
   653→// Stream end
   654→{
   655→  "type": "STREAM_END",
   656→  "payload": {
   657→    "cardId": "card_007",
   658→    "card": { /* Complete TurnCard */ }
   659→  }
   660→}
   661→```
   662→
   663→### 13.5 Action Dispatch
   664→
   665→Client can dispatch actions via WebSocket:
   666→
   667→```typescript
   668→// Client sends
   669→{
   670→  "type": "ACTION",
   671→  "payload": {
   672→    "sessionId": "sess_abc123",
   673→    "action": {
   674→      "type": "SELECT_CARD",
   675→      "payload": { "index": 3 }
   676→    }
   677→  },
   678→  "correlationId": "req_123"
   679→}
   680→
   681→// Server responds
   682→{
   683→  "type": "STATE_UPDATE",
   684→  "payload": {
   685→    "quadrants": { /* Updated quadrant state */ }
   686→  },
   687→  "correlationId": "req_123"
   688→}
   689→```
   690→
   691→---
   692→
   693→## 14. Error Handling
   694→
   695→### 14.1 Error Response Format
   696→
   697→```typescript
   698→interface ErrorResponse {
   699→  error: {
   700→    code: string;
   701→    message: string;
   702→    details?: Record<string, unknown>;
   703→  };
   704→}
   705→```
   706→
   707→### 14.2 Error Codes
   708→
   709→| Code | HTTP Status | Description |
