   830→
   831→### 10.2 Streaming Handler
   832→
   833→```typescript
   834→export const streamCompletion = async (
   835→  messages: ChatMessage[],
   836→  onChunk: (content: string, index: number) => void,
   837→  onComplete: (fullContent: string) => void,
   838→  onError: (error: Error) => void
   839→): Promise<void> => {
   840→  try {
   841→    const stream = await openai.chat.completions.create({
   842→      model: config.model,  // "gpt-4" or "gpt-4-turbo"
   843→      messages,
   844→      stream: true,
   845→    });
   846→
   847→    let fullContent = "";
   848→    let index = 0;
   849→
   850→    for await (const chunk of stream) {
   851→      const content = chunk.choices[0]?.delta?.content || "";
   852→      if (content) {
   853→        fullContent += content;
   854→        onChunk(content, index++);
   855→      }
   856→    }
   857→
   858→    onComplete(fullContent);
   859→  } catch (error) {
   860→    onError(error as Error);
   861→  }
   862→};
   863→```
   864→
   865→### 10.3 Message Building
   866→
   867→```typescript
   868→export const buildMessages = (
   869→  systemPrompt: string,
   870→  cards: TurnCard[],
   871→  newUserMessage: string
   872→): ChatMessage[] => {
   873→  const messages: ChatMessage[] = [
   874→    { role: "system", content: systemPrompt }
   875→  ];
   876→
   877→  // Add conversation history
   878→  for (const card of cards) {
   879→    messages.push({ role: "user", content: card.userContent });
   880→    messages.push({ role: "assistant", content: card.aiContent });
   881→  }
   882→
   883→  // Add new message
   884→  messages.push({ role: "user", content: newUserMessage });
   885→
   886→  return messages;
   887→};
   888→```
